def run_v116(args):
    old = sys.argv[:]
    try:
        sys.argv = ["mfp3_v116_embedded.py"]
        if args.full:
            sys.argv.append("--full")

        g = {
            "__name__": "mfp3_v116_embedded",
            "__file__": "<embedded:v1.16>",
            "__builtins__": __builtins__,
        }
        exec(compile(V116_SOURCE, g["__file__"], "exec"), g, g)
        g["main"]()
    finally:
        sys.argv = old

