def fetch_bytes(url, timeout=45):
    req = urllib.request.Request(
        url,
        headers={
            "User-Agent": "Mozilla/5.0 MFP3-Research/1.17"
        },
    )
    with urllib.request.urlopen(req, timeout=timeout) as r:
        return r.read()

def cached_download(name, url, max_age_hours=24):
    path = CACHE / name

    if path.exists():
        age = (
            datetime.now(timezone.utc).timestamp()
            - path.stat().st_mtime
        ) / 3600.0
        if age <= max_age_hours:
            return path

    data = fetch_bytes(url)
    path.write_bytes(data)
    return path

def source_record(status, name, ok, detail=""):
    status[name] = {
        "ok": bool(ok),
        "detail": str(detail)[:500],
    }

