def load_v14():
    if not V14_DAILY.exists():
        raise RuntimeError(
            "Falta mfp3_fusion_lab/fusion_daily.csv. "
            "La cadena debe llegar al menos a v1.14."
        )

    x = pd.read_csv(
        V14_DAILY,
        index_col=0,
        parse_dates=True,
    ).sort_index()

    needed = {
        "v17_ret",
        "synergy_ret",
        "benchmark_ret",
        "v17_weight",
        "fusion_ret",
    }

    missing = needed - set(x.columns)
    if missing:
        raise RuntimeError(
            f"Faltan columnas de v1.14: {missing}"
        )

    x.index = pd.to_datetime(x.index).tz_localize(None)
    return x

def monthly_compound(s):
    return (
        (1 + s.fillna(0.0))
        .groupby(s.index.to_period("M"))
        .prod()
        - 1.0
    )

def monthly_targets(x):
    m = pd.DataFrame()

    m["v17_ret"] = monthly_compound(x["v17_ret"])
    m["synergy_ret"] = monthly_compound(x["synergy_ret"])
    m["v14_ret"] = monthly_compound(x["fusion_ret"])
    m["benchmark_ret"] = monthly_compound(x["benchmark_ret"])

    # Target: relative advantage of Synergy over v1.7 for the month.
    m["synergy_edge"] = (
        m["synergy_ret"] - m["v17_ret"]
    )

    # Use first actual v1.14 weight of month as base allocation.
    m["base_v14_v17_weight"] = (
        x["v17_weight"]
        .groupby(x.index.to_period("M"))
        .first()
    )

    m.index = m.index.to_timestamp()
    return m

# ------------------------------------------------------------
# Deterministic astronomy/calendar features
# ------------------------------------------------------------

# Approximate known new-moon epoch:
# 2000-01-06 18:14 UTC, synodic month 29.530588853 days.
MOON_EPOCH = pd.Timestamp("2000-01-06 18:14:00")
SYNODIC = 29.530588853

def moon_phase_fraction(dt):
    days = (
        pd.Timestamp(dt) - MOON_EPOCH
    ).total_seconds() / 86400.0
    return (days / SYNODIC) % 1.0

def cyclical_features(index):
    f = pd.DataFrame(index=index)

    month = index.month.to_numpy()
    quarter = index.quarter.to_numpy()
    doy = index.dayofyear.to_numpy()

    f["month_sin"] = np.sin(2 * np.pi * month / 12.0)
    f["month_cos"] = np.cos(2 * np.pi * month / 12.0)
    f["quarter_sin"] = np.sin(2 * np.pi * quarter / 4.0)
    f["quarter_cos"] = np.cos(2 * np.pi * quarter / 4.0)
    f["year_sin"] = np.sin(2 * np.pi * doy / 365.25)
    f["year_cos"] = np.cos(2 * np.pi * doy / 365.25)

    phases = np.array(
        [moon_phase_fraction(dt) for dt in index]
    )

    f["moon_sin"] = np.sin(2 * np.pi * phases)
    f["moon_cos"] = np.cos(2 * np.pi * phases)

    # 0=new moon, 0.5=full moon.
    dist_full = np.minimum(
        np.abs(phases - 0.5),
        1 - np.abs(phases - 0.5),
    )
    dist_new = np.minimum(
        np.abs(phases),
        1 - np.abs(phases),
    )

    f["full_moon_proximity"] = np.clip(
        1 - dist_full / 0.25,
        0,
        1,
    )
    f["new_moon_proximity"] = np.clip(
        1 - dist_new / 0.25,
        0,
        1,
    )

    # Known calendar effects / cycles.
    f["january"] = (month == 1).astype(float)
    f["quarter_start"] = np.isin(
        month, [1, 4, 7, 10]
    ).astype(float)
    f["year_end_window"] = np.isin(
        month, [11, 12]
    ).astype(float)

    return f

