OLYMPICS = [
    ("WINTER", "2006-02-10", "2006-02-26"),
    ("SUMMER", "2008-08-08", "2008-08-24"),
    ("WINTER", "2010-02-12", "2010-02-28"),
    ("SUMMER", "2012-07-27", "2012-08-12"),
    ("WINTER", "2014-02-07", "2014-02-23"),
    ("SUMMER", "2016-08-05", "2016-08-21"),
    ("WINTER", "2018-02-09", "2018-02-25"),
    ("SUMMER", "2021-07-23", "2021-08-08"),
    ("WINTER", "2022-02-04", "2022-02-20"),
    ("SUMMER", "2024-07-26", "2024-08-11"),
    ("WINTER", "2026-02-06", "2026-02-22"),
]

def olympic_features(index):
    f = pd.DataFrame(
        0.0,
        index=index,
        columns=[
            "olympics_active",
            "olympics_pre30",
            "olympics_post30",
            "olympics_summer",
            "olympics_winter",
        ],
    )

    for kind, start, end in OLYMPICS:
        s = pd.Timestamp(start)
        e = pd.Timestamp(end)

        active = (index >= s) & (index <= e)
        pre = (
            (index >= s - pd.Timedelta(days=30))
            & (index < s)
        )
        post = (
            (index > e)
            & (index <= e + pd.Timedelta(days=30))
        )

        f.loc[active, "olympics_active"] = 1.0
        f.loc[pre, "olympics_pre30"] = 1.0
        f.loc[post, "olympics_post30"] = 1.0

        if kind == "SUMMER":
            f.loc[
                active | pre | post,
                "olympics_summer",
            ] = 1.0
        else:
            f.loc[
                active | pre | post,
                "olympics_winter",
            ] = 1.0

    return f

# ------------------------------------------------------------
# FRED expectations
# ------------------------------------------------------------

FRED_SERIES = {
    "t10yie": ("T10YIE", "daily"),
    "t5yie": ("T5YIE", "daily"),
    "sentiment": ("UMCSENT", "monthly"),
    "mich_infl_exp": ("MICH", "monthly"),
    "expinf1yr": ("EXPINF1YR", "monthly"),
    "expinf10yr": ("EXPINF10YR", "monthly"),
}

def fetch_fred_series(series_id):
    url = (
        "https://fred.stlouisfed.org/graph/"
        f"fredgraph.csv?id={series_id}"
    )
    path = cached_download(
        f"fred_{series_id}.csv",
        url,
        max_age_hours=24,
    )

    df = pd.read_csv(path)
    date_col = df.columns[0]
    value_col = df.columns[-1]

    idx = pd.to_datetime(
        df[date_col],
        errors="coerce",
    )
    val = pd.to_numeric(
        df[value_col],
        errors="coerce",
    )

    s = pd.Series(
        val.to_numpy(),
        index=idx,
        name=series_id,
    ).dropna()

    return s.sort_index()

def expectations_features(month_index, status):
    daily_idx = pd.date_range(
        month_index.min() - pd.Timedelta(days=90),
        month_index.max() + pd.Timedelta(days=5),
        freq="D",
    )

    out = pd.DataFrame(index=daily_idx)

    for name, (sid, freq) in FRED_SERIES.items():
        try:
            s = fetch_fred_series(sid)

            # Conservative availability lag.
            if freq == "daily":
                s.index = s.index + pd.Timedelta(days=1)
            else:
                # Monthly releases are not assumed known on observation date.
                s.index = s.index + pd.Timedelta(days=35)

            aligned = (
                s.reindex(
                    s.index.union(daily_idx)
                )
                .sort_index()
                .ffill()
                .reindex(daily_idx)
            )

            out[name] = aligned

            out[f"{name}_chg30"] = (
                out[name].diff(30)
            )

            roll = out[name].rolling(365, min_periods=90)
            out[f"{name}_z365"] = (
                out[name] - roll.mean()
            ) / roll.std().replace(0, np.nan)

            source_record(
                status,
                f"FRED_{sid}",
                True,
                f"{len(s)} observations",
            )

        except Exception as e:
            source_record(
                status,
                f"FRED_{sid}",
                False,
                repr(e),
            )

    return out.reindex(month_index, method="ffill")

