AI_GPR_URL = (
    "https://www.matteoiacoviello.com/"
    "ai_gpr_files/ai_gpr_data_daily.csv"
)

def geopolitical_features(month_index, status):
    try:
        path = cached_download(
            "ai_gpr_data_daily.csv",
            AI_GPR_URL,
            max_age_hours=24,
        )
        df = pd.read_csv(path)

        # Detect a date column.
        date_col = None
        for c in df.columns:
            if str(c).lower() in {
                "date", "day", "datetime"
            }:
                date_col = c
                break

        if date_col is None:
            date_col = df.columns[0]

        idx = pd.to_datetime(
            df[date_col],
            errors="coerce",
        )

        numeric = df.copy()
        numeric.index = idx
        numeric = numeric.drop(
            columns=[date_col],
            errors="ignore",
        )
        numeric = numeric.apply(
            pd.to_numeric,
            errors="coerce",
        )
        numeric = numeric.loc[
            ~numeric.index.isna()
        ].sort_index()

        # Use up to the first 8 useful numeric components.
        numeric = numeric.dropna(
            axis=1,
            how="all",
        ).iloc[:, :8]

        # One-day lag before market use.
        numeric.index = (
            numeric.index + pd.Timedelta(days=1)
        )

        daily_idx = pd.date_range(
            month_index.min() - pd.Timedelta(days=100),
            month_index.max(),
            freq="D",
        )

        z = (
            numeric.reindex(
                numeric.index.union(daily_idx)
            )
            .sort_index()
            .ffill()
            .reindex(daily_idx)
        )

        out = pd.DataFrame(index=daily_idx)

        for i, c in enumerate(z.columns):
            name = (
                "gpr_"
                + str(c)
                .lower()
                .replace(" ", "_")
                .replace("-", "_")
            )

            out[name] = z[c]
            out[f"{name}_ma21"] = z[c].rolling(21).mean()
            out[f"{name}_ma63"] = z[c].rolling(63).mean()

            r = z[c].rolling(252, min_periods=63)
            out[f"{name}_z252"] = (
                z[c] - r.mean()
            ) / r.std().replace(0, np.nan)

        source_record(
            status,
            "AI_GPR",
            True,
            f"{len(numeric)} daily rows; {len(numeric.columns)} components",
        )

        return out.reindex(
            month_index,
            method="ffill",
        )

    except Exception as e:
        source_record(
            status,
            "AI_GPR",
            False,
            repr(e),
        )
        return pd.DataFrame(index=month_index)

# ------------------------------------------------------------
# NOAA Niño 3.4
# ------------------------------------------------------------

NINO_URL = (
    "https://psl.noaa.gov/data/timeseries/month/"
    "data/nino34.long.anom.csv"
)

def nino_features(month_index, status):
    try:
        path = cached_download(
            "nino34.csv",
            NINO_URL,
            max_age_hours=72,
        )

        df = pd.read_csv(path)
        cols = [str(c).lower() for c in df.columns]

        s = None

        # Common CSV form: date,value
        if len(df.columns) >= 2:
            date_try = pd.to_datetime(
                df.iloc[:, 0],
                errors="coerce",
            )
            val_try = pd.to_numeric(
                df.iloc[:, 1],
                errors="coerce",
            )

            if date_try.notna().mean() > 0.7:
                s = pd.Series(
                    val_try.to_numpy(),
                    index=date_try,
                ).dropna()

        # Alternate year/month/value form.
        if s is None and len(df.columns) >= 3:
            year = pd.to_numeric(
                df.iloc[:, 0],
                errors="coerce",
            )
            month = pd.to_numeric(
                df.iloc[:, 1],
                errors="coerce",
            )
            val = pd.to_numeric(
                df.iloc[:, 2],
                errors="coerce",
            )

            idx = pd.to_datetime(
                dict(
                    year=year,
                    month=month,
                    day=1,
                ),
                errors="coerce",
            )

            s = pd.Series(
                val.to_numpy(),
                index=idx,
            ).dropna()

        if s is None or s.empty:
            raise ValueError(
                "No pude interpretar el CSV Niño3.4."
            )

        s = s.sort_index()

        # Conservative publication/revision lag.
        s.index = (
            s.index + pd.Timedelta(days=45)
        )

        daily_idx = pd.date_range(
            month_index.min() - pd.Timedelta(days=400),
            month_index.max(),
            freq="D",
        )

        a = (
            s.reindex(
                s.index.union(daily_idx)
            )
            .sort_index()
            .ffill()
            .reindex(daily_idx)
        )

        out = pd.DataFrame(index=daily_idx)
        out["nino34"] = a
        out["nino34_chg90"] = a.diff(90)
        out["elnino_flag"] = (a >= 0.5).astype(float)
        out["lanina_flag"] = (a <= -0.5).astype(float)

        source_record(
            status,
            "NOAA_NINO34",
            True,
            f"{len(s)} monthly observations",
        )

        return out.reindex(
            month_index,
            method="ffill",
        )

    except Exception as e:
        source_record(
            status,
            "NOAA_NINO34",
            False,
            repr(e),
        )
        return pd.DataFrame(index=month_index)

# ------------------------------------------------------------
# Open-Meteo historical weather
# ------------------------------------------------------------

WEATHER_CITIES = {
    "newyork": (40.7128, -74.0060),
    "beijing": (39.9042, 116.4074),
    "santiago": (-33.4489, -70.6693),
    "antofagasta": (-23.6509, -70.3975),
}

def fetch_weather_city(
    name,
    lat,
    lon,
    start,
    end,
):
    params = {
        "latitude": lat,
        "longitude": lon,
        "start_date": start.strftime("%Y-%m-%d"),
        "end_date": end.strftime("%Y-%m-%d"),
        "daily": (
            "temperature_2m_mean,"
            "precipitation_sum,"
            "wind_speed_10m_max"
        ),
        "timezone": "UTC",
    }

    url = (
        "https://archive-api.open-meteo.com/v1/archive?"
        + urllib.parse.urlencode(params)
    )

    path = cached_download(
        f"weather_{name}.json",
        url,
        max_age_hours=168,
    )

    data = json.loads(
        path.read_text(encoding="utf-8")
    )

    daily = data["daily"]
    idx = pd.to_datetime(daily["time"])

    out = pd.DataFrame(index=idx)

    for key in [
        "temperature_2m_mean",
        "precipitation_sum",
        "wind_speed_10m_max",
    ]:
        out[key] = pd.to_numeric(
            daily.get(key, []),
            errors="coerce",
        )

    return out

def weather_features(month_index, status):
    start = (
        month_index.min()
        - pd.Timedelta(days=400)
    )
    # Archive data can lag current date; request through yesterday.
    end = min(
        month_index.max(),
        pd.Timestamp.now().normalize()
        - pd.Timedelta(days=1),
    )

    merged = pd.DataFrame(index=month_index)

    for name, (lat, lon) in WEATHER_CITIES.items():
        try:
            w = fetch_weather_city(
                name,
                lat,
                lon,
                start,
                end,
            )

            # Information through previous day only.
            w = w.shift(1)

            for c in w.columns:
                s = w[c]
                merged[
                    f"{name}_{c}_ma30"
                ] = (
                    s.rolling(
                        30,
                        min_periods=15,
                    )
                    .mean()
                    .reindex(
                        month_index,
                        method="ffill",
                    )
                )

                # anomaly vs trailing year
                trailing = s.rolling(
                    365,
                    min_periods=120,
                )
                anomaly = (
                    s - trailing.mean()
                ) / trailing.std().replace(
                    0,
                    np.nan,
                )

                merged[
                    f"{name}_{c}_anom365"
                ] = anomaly.reindex(
                    month_index,
                    method="ffill",
                )

            source_record(
                status,
                f"WEATHER_{name.upper()}",
                True,
                f"{len(w)} daily observations",
            )

        except Exception as e:
            source_record(
                status,
                f"WEATHER_{name.upper()}",
                False,
                repr(e),
            )

    return merged

