GROUPS = {}

def build_features(month_index):
    status = {}
    parts = []

    cal = cyclical_features(month_index)
    oly = olympic_features(month_index)
    expectations = expectations_features(
        month_index,
        status,
    )
    gpr = geopolitical_features(
        month_index,
        status,
    )
    nino = nino_features(
        month_index,
        status,
    )
    weather = weather_features(
        month_index,
        status,
    )

    parts = [
        cal,
        oly,
        expectations,
        gpr,
        nino,
        weather,
    ]

    X = pd.concat(
        parts,
        axis=1,
    )

    # Remove duplicate/empty columns.
    X = X.loc[:, ~X.columns.duplicated()]
    X = X.dropna(
        axis=1,
        how="all",
    )

    group_map = {
        "CALENDAR": [
            c for c in X.columns
            if c in {
                "month_sin",
                "month_cos",
                "quarter_sin",
                "quarter_cos",
                "year_sin",
                "year_cos",
                "january",
                "quarter_start",
                "year_end_window",
            }
        ],
        "MOON": [
            c for c in X.columns
            if c.startswith("moon_")
            or c in {
                "full_moon_proximity",
                "new_moon_proximity",
            }
        ],
        "OLYMPICS": [
            c for c in X.columns
            if c.startswith("olympics_")
        ],
        "EXPECTATIONS": [
            c for c in X.columns
            if c.startswith(
                (
                    "t10yie",
                    "t5yie",
                    "sentiment",
                    "mich_infl_exp",
                    "expinf",
                )
            )
        ],
        "GEOPOLITICAL": [
            c for c in X.columns
            if c.startswith("gpr_")
        ],
        "CLIMATE_ENSO": [
            c for c in X.columns
            if c.startswith("nino")
            or c in {
                "elnino_flag",
                "lanina_flag",
            }
        ],
        "WEATHER": [
            c for c in X.columns
            if c.startswith(
                tuple(
                    name + "_"
                    for name in WEATHER_CITIES
                )
            )
        ],
    }

    # Keep only non-empty groups.
    group_map = {
        k: v for k, v in group_map.items()
        if len(v)
    }

    SOURCE_STATUS_JSON.write_text(
        json.dumps(
            {
                "updated_at_utc":
                    datetime.now(timezone.utc)
                    .isoformat(timespec="seconds"),
                "sources": status,
                "groups": {
                    k: len(v)
                    for k, v in group_map.items()
                },
            },
            indent=2,
            ensure_ascii=False,
        ),
        encoding="utf-8",
    )

    return X, group_map, status

# ------------------------------------------------------------
# Walk-forward group predictions
# ------------------------------------------------------------

def ridge_model():
    return Pipeline([
        (
            "imp",
            SimpleImputer(
                strategy="median",
                add_indicator=True,
            ),
        ),
        (
            "sc",
            StandardScaler(),
        ),
        (
            "m",
            Ridge(alpha=15.0),
        ),
    ])

def expanding_group_predictions(
    data,
    group_map,
):
    y = data["synergy_edge"]
    preds = pd.DataFrame(
        np.nan,
        index=data.index,
        columns=list(group_map.keys()),
    )

    for i in range(
        MIN_TRAIN_MONTHS,
        len(data),
    ):
        train = data.iloc[:i]
        test = data.iloc[[i]]

        for group, cols in group_map.items():
            use = [
                c for c in cols
                if c in data.columns
            ]

            if not use:
                continue

            tr = train[
                use + ["synergy_edge"]
            ].copy()

            # Need enough target values and at least some feature coverage.
            if tr["synergy_edge"].notna().sum() < MIN_TRAIN_MONTHS:
                continue

            coverage = (
                tr[use].notna().mean().mean()
            )

            if coverage < 0.50:
                continue

            model = ridge_model()

            try:
                model.fit(
                    tr[use],
                    tr["synergy_edge"],
                )
                pred = float(
                    model.predict(
                        test[use]
                    )[0]
                )
                preds.loc[
                    data.index[i],
                    group,
                ] = pred
            except Exception:
                pass

    return preds

def score_groups_until(
    preds,
    actual,
    end_pos,
):
    rows = []

    hist_idx = preds.index[:end_pos]
    hist_idx = hist_idx[
        max(
            0,
            len(hist_idx)
            - SCORE_WINDOW_MONTHS
        ):
    ]

    for group in preds.columns:
        z = pd.DataFrame({
            "pred": preds.loc[
                hist_idx,
                group,
            ],
            "actual": actual.loc[
                hist_idx
            ],
        }).dropna()

        if len(z) < MIN_SCORE_MONTHS:
            continue

        ic = z["pred"].rank().corr(
            z["actual"].rank()
        )

        if pd.isna(ic):
            continue

        direction = float(
            (
                np.sign(z["pred"])
                == np.sign(z["actual"])
            ).mean()
        )

        # Stability: IC first half vs second half.
        mid = len(z) // 2
        z1 = z.iloc[:mid]
        z2 = z.iloc[mid:]

        ic1 = (
            z1["pred"].rank().corr(
                z1["actual"].rank()
            )
            if len(z1) >= 8
            else np.nan
        )
        ic2 = (
            z2["pred"].rank().corr(
                z2["actual"].rank()
            )
            if len(z2) >= 8
            else np.nan
        )

        stable = (
            pd.notna(ic1)
            and pd.notna(ic2)
            and ic1 > -0.02
            and ic2 > -0.02
        )

        # Candidate must show positive OOS relationship.
        accepted = (
            ic > 0.05
            and direction >= 0.50
            and stable
        )

        score = (
            max(0.0, float(ic))
            * np.sqrt(len(z))
            * max(
                0.05,
                direction - 0.45,
            )
        )

        rows.append({
            "group": group,
            "n": len(z),
            "ic": float(ic),
            "directional_accuracy": direction,
            "ic_first_half": (
                float(ic1)
                if pd.notna(ic1)
                else np.nan
            ),
            "ic_second_half": (
                float(ic2)
                if pd.notna(ic2)
                else np.nan
            ),
            "stable": bool(stable),
            "accepted": bool(accepted),
            "score": score if accepted else 0.0,
        })

    return pd.DataFrame(rows)

def ensemble_prediction(
    preds,
    actual,
    pos,
):
    tests = score_groups_until(
        preds,
        actual,
        pos,
    )

    if tests.empty:
        return 0.0, tests

    accepted = tests[
        tests["accepted"]
    ].copy()

    if accepted.empty:
        return 0.0, tests

    current = preds.iloc[pos]

    accepted = accepted[
        accepted["group"].isin(
            current.dropna().index
        )
    ]

    if accepted.empty:
        return 0.0, tests

    total = accepted["score"].sum()

    if total <= 0:
        return 0.0, tests

    accepted["weight"] = (
        accepted["score"] / total
    )

    pred = 0.0

    for r in accepted.itertuples():
        pred += (
            float(r.weight)
            * float(
                current[r.group]
            )
        )

    return float(pred), tests

# ------------------------------------------------------------
# Map exogenous expected edge to overlay delta
# ------------------------------------------------------------

def edge_to_delta(pred):
    # Positive predicted edge => Synergy expected to outperform v1.7,
    # therefore REDUCE v1.7 weight.
    if pred >= 0.010:
        return -0.12
    if pred >= 0.006:
        return -0.08
    if pred >= 0.003:
        return -0.04

    if pred <= -0.010:
        return +0.10
    if pred <= -0.006:
        return +0.07
    if pred <= -0.003:
        return +0.04

    return 0.0

# ------------------------------------------------------------
# Placebo reporting by circular shifts
# ------------------------------------------------------------

def placebo_group_tests(
    preds,
    actual,
    seed=42,
):
    rng = np.random.default_rng(seed)
    rows = []

    for group in preds.columns:
        z = pd.DataFrame({
            "pred": preds[group],
            "actual": actual,
        }).dropna()

        if len(z) < 36:
            continue

        observed = z["pred"].rank().corr(
            z["actual"].rank()
        )

        if pd.isna(observed):
            continue

        null = []

        # Circular shifts preserve much of target autocorrelation.
        possible = np.arange(
            6,
            max(7, len(z) - 6),
        )

        if len(possible) == 0:
            continue

        shifts = rng.choice(
            possible,
            size=min(100, len(possible) * 2),
            replace=True,
        )

        a = z["actual"].to_numpy()
        p = z["pred"].rank().to_numpy()

        for sh in shifts:
            shifted = np.roll(a, int(sh))
            corr = pd.Series(p).corr(
                pd.Series(shifted).rank()
            )
            if pd.notna(corr):
                null.append(float(corr))

        if null:
            pvalue = (
                1
                + np.sum(
                    np.abs(null)
                    >= abs(float(observed))
                )
            ) / (1 + len(null))
        else:
            pvalue = np.nan

        rows.append({
            "group": group,
            "oos_ic_full": float(observed),
            "n_oos": len(z),
            "placebo_pvalue": pvalue,
        })

    return pd.DataFrame(rows)

# ------------------------------------------------------------
# Walk-forward overlay
# ------------------------------------------------------------

def run_exogenous_lab():
    x = load_v14()
    monthly = monthly_targets(x)

    # Need a stable common monthly start index.
    month_index = monthly.index

    print(
        "[v1.17] Descargando/construyendo factores exógenos..."
    )

    features, group_map, status = build_features(
        month_index
    )

    data = monthly.join(
        features,
        how="left",
    )

    data.to_csv(
        FEATURES_CSV,
        encoding="utf-8-sig",
    )

    print(
        "[v1.17] Generando predicciones walk-forward "
        "por familia..."
    )

    group_preds = expanding_group_predictions(
        data,
        group_map,
    )

    decisions = []
    test_history = []

    for i in range(
        MIN_TRAIN_MONTHS,
        len(data),
    ):
        pred, tests = ensemble_prediction(
            group_preds,
            data["synergy_edge"],
            i,
        )

        delta = edge_to_delta(pred)

        accepted = (
            tests[
                tests["accepted"]
            ]["group"].tolist()
            if not tests.empty
            else []
        )

        decisions.append({
            "month": data.index[i],
            "predicted_synergy_edge": pred,
            "exogenous_delta_v17": delta,
            "accepted_groups":
                " | ".join(accepted),
            "actual_synergy_edge":
                float(data["synergy_edge"].iloc[i])
                if pd.notna(
                    data["synergy_edge"].iloc[i]
                )
                else np.nan,
        })

    decisions_df = pd.DataFrame(
        decisions
    )

    if not decisions_df.empty:
        decisions_df["month"] = pd.to_datetime(
            decisions_df["month"]
        )
        decisions_df = decisions_df.set_index(
            "month"
        )

    # Monthly delta mapped to each trading day.
    delta_by_month = (
        decisions_df[
            "exogenous_delta_v17"
        ]
        if len(decisions_df)
        else pd.Series(dtype=float)
    )

    daily_month = x.index.to_period("M").to_timestamp()

    deltas = pd.Series(
        [
            float(
                delta_by_month.get(
                    m,
                    0.0,
                )
            )
            for m in daily_month
        ],
        index=x.index,
    )

    out = x.copy()
    out["exogenous_delta_v17"] = deltas

    out["v17_weight_exogenous"] = (
        out["v17_weight"]
        + out["exogenous_delta_v17"]
    ).clip(
        0.50,
        1.00,
    )

    out["synergy_weight_exogenous"] = (
        1.0
        - out["v17_weight_exogenous"]
    )

    out["exogenous_ret"] = (
        out["v17_weight_exogenous"]
        * out["v17_ret"]
        + out["synergy_weight_exogenous"]
        * out["synergy_ret"]
    )

    out["capital_exogenous"] = (
        INITIAL_CAPITAL
        * (1 + out["exogenous_ret"]).cumprod()
    )

    out["capital_v14"] = (
        INITIAL_CAPITAL
        * (1 + out["fusion_ret"]).cumprod()
    )

    out["capital_v17"] = (
        INITIAL_CAPITAL
        * (1 + out["v17_ret"]).cumprod()
    )

    out["capital_synergy"] = (
        INITIAL_CAPITAL
        * (1 + out["synergy_ret"]).cumprod()
    )

    out["capital_benchmark"] = (
        INITIAL_CAPITAL
        * (1 + out["benchmark_ret"]).cumprod()
    )

    def perf(ret):
        r = pd.Series(ret).fillna(0.0)
        curve = (1 + r).cumprod()
        total = float(curve.iloc[-1] - 1.0)

        years = max(
            len(r) / 252.0,
            1 / 252.0,
        )
        cagr = float(
            curve.iloc[-1] ** (1 / years) - 1
        )

        vol = float(
            r.std() * np.sqrt(252)
        )
        sharpe = (
            float(
                r.mean() * 252 / vol
            )
            if vol > 1e-12
            else 0.0
        )

        dd = (
            curve / curve.cummax() - 1
        )

        return {
            "total_return": total,
            "cagr": cagr,
            "sharpe": sharpe,
            "max_drawdown": float(
                dd.min()
            ),
            "ann_vol": vol,
        }

    metrics = pd.DataFrame([
        {
            "name":
                "EXOGENOUS_DISCOVERY_CHALLENGER",
            **perf(out["exogenous_ret"]),
        },
        {
            "name":
                "V14_ADAPTIVE_FUSION_REFERENCE",
            **perf(out["fusion_ret"]),
        },
        {
            "name":
                "V17_REFERENCE_COMMON_WINDOW",
            **perf(out["v17_ret"]),
        },
        {
            "name":
                "SYNERGY_REFERENCE_COMMON_WINDOW",
            **perf(out["synergy_ret"]),
        },
        {
            "name":
                "BENCHMARK_COMMON_WINDOW",
            **perf(out["benchmark_ret"]),
        },
    ])

    placebo = placebo_group_tests(
        group_preds,
        data["synergy_edge"],
    )

    # Full-sample reporting only; not used to make historical decisions.
    report_rows = []

    for group in group_preds.columns:
        z = pd.DataFrame({
            "pred": group_preds[group],
            "actual": data["synergy_edge"],
        }).dropna()

        if len(z) < 12:
            continue

        ic = z["pred"].rank().corr(
            z["actual"].rank()
        )

        direction = float(
            (
                np.sign(z["pred"])
                == np.sign(z["actual"])
            ).mean()
        )

        report_rows.append({
            "group": group,
            "n_oos": len(z),
            "oos_ic": float(ic)
                if pd.notna(ic)
                else np.nan,
            "directional_accuracy":
                direction,
        })

    group_report = pd.DataFrame(
        report_rows
    )

    if not placebo.empty:
        group_report = group_report.merge(
            placebo,
            on="group",
            how="left",
            suffixes=("", "_placebo"),
        )

    out.to_csv(
        DAILY_CSV,
        encoding="utf-8-sig",
    )

    decisions_df.to_csv(
        WALKFORWARD_CSV,
        encoding="utf-8-sig",
    )

    group_report.to_csv(
        GROUP_TESTS_CSV,
        index=False,
        encoding="utf-8-sig",
    )

    metrics.to_csv(
        METRICS_CSV,
        index=False,
        encoding="utf-8-sig",
    )

    latest_month = (
        decisions_df.index.max()
        if len(decisions_df)
        else None
    )

    latest_delta = (
        float(
            decisions_df.loc[
                latest_month,
                "exogenous_delta_v17",
            ]
        )
        if latest_month is not None
        else 0.0
    )

    latest_groups = (
        str(
            decisions_df.loc[
                latest_month,
                "accepted_groups",
            ]
        )
        if latest_month is not None
        else ""
    )

    STATE_JSON.write_text(
        json.dumps(
            {
                "last_completed_utc":
                    datetime.now(timezone.utc)
                    .isoformat(timespec="seconds"),
                "version": "v1.17",
                "latest_month":
                    str(latest_month),
                "latest_exogenous_delta_v17":
                    latest_delta,
                "latest_accepted_groups":
                    latest_groups,
                "feature_groups": {
                    k: len(v)
                    for k, v in group_map.items()
                },
            },
            indent=2,
            ensure_ascii=False,
        ),
        encoding="utf-8",
    )

    return (
        out,
        decisions_df,
        metrics,
        group_report,
        group_map,
    )

# ------------------------------------------------------------
# Cadence
# ------------------------------------------------------------

def exogenous_due(force=False):
    if force or not STATE_JSON.exists():
        return True

    try:
        s = json.loads(
            STATE_JSON.read_text(
                encoding="utf-8"
            )
        )

        last = pd.Timestamp(
            s["last_completed_utc"]
        )

        if last.tzinfo is None:
            last = last.tz_localize("UTC")
        else:
            last = last.tz_convert("UTC")

        return (
            pd.Timestamp.now(tz="UTC")
            - last
        ).days >= RUN_EVERY_DAYS

    except Exception:
        return True

